diff --git a/packages/metrics/lib/observeApiError.ts b/packages/metrics/lib/observeApiError.ts
new file mode 100644
index 0000000000..8afe66b5fb
--- /dev/null
+++ b/packages/metrics/lib/observeApiError.ts
@@ -0,0 +1,21 @@
+export type MetricsApiStatusTypes = '4xx' | '5xx' | 'failure';
+
+export const observeApiError = (
+    error: any,
+    metricObserver: (status: MetricsApiStatusTypes) => void
+): void => {
+    if (!error) {
+        metricObserver('failure');
+        return;
+    }
+
+    const { status } = error;
+
+    if (status >= 500) {
+        metricObserver('5xx');
+    } else if (status >= 400) {
+        metricObserver('4xx');
+    } else {
+        metricObserver('failure');
+    }
+};
